"use client";

import React, { useState } from "react";
import Link from "next/link";
import { Clock, ExternalLink, ChevronDown, ChevronUp, Newspaper, Train, ArrowRight } from "lucide-react";
import { analytics } from "@/lib/analytics";

export interface ImpactedTrainDetail {
  trainNo: string;
  trainName?: string;
  status: "fully_cancelled" | "partially_cancelled" | "diverted" | "affected" | string;
  journeyDate?: string;
  route?: {
    source?: { code?: string | null; name?: string | null };
    destination?: { code?: string | null; name?: string | null };
  } | null;
  cancelledSegment?: {
    from?: { code?: string | null; name?: string | null };
    to?: { code?: string | null; name?: string | null };
  } | null;
  reportedAt?: string;
}

export interface NewsArticle {
  id: string;
  title: string;
  summary: string;
  sourceName: string;
  sourceUrl: string;
  publishedAt: string;
  updatedAt?: string;
  category: string;
  imageUrl: string | null;
  slug?: string | null;
  seoTitle?: string | null;
  metaDescription?: string | null;
  keyTakeaways?: string[];
  passengerAdvice?: string | null;
  faq?: Array<{ question: string; answer: string }>;
  affectedTrains?: string[];
  affectedTrainsDetail?: ImpactedTrainDetail[];
  affectedStations?: string[];
  content?: string | null;
}

interface NewsCardProps {
  article: NewsArticle;
  categoryIcon: React.ReactNode;
  categoryColor: string;
}

function formatRelativeTime(iso: string): string {
  const now = Date.now();
  const then = new Date(iso).getTime();
  if (isNaN(then)) return "";
  const diffMs = now - then;
  const diffMins = Math.floor(diffMs / 60000);
  const diffHrs = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHrs / 24);
  if (diffMins < 1) return "Just now";
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHrs < 24) return `${diffHrs}h ago`;
  if (diffDays < 7) return `${diffDays}d ago`;
  return new Date(iso).toLocaleDateString("en-IN", {
    day: "numeric",
    month: "short",
    year: diffDays > 365 ? "numeric" : undefined,
  });
}

function isValidUrl(url: string | null | undefined): boolean {
  if (!url || url === "#" || url.trim() === "") return false;
  try {
    const u = new URL(url);
    return u.protocol === "https:" || u.protocol === "http:";
  } catch {
    return false;
  }
}

export default function NewsCard({ article, categoryIcon, categoryColor }: NewsCardProps) {
  const [expanded, setExpanded] = useState(false);
  const [imageError, setImageError] = useState(false);
  const hasValidUrl = isValidUrl(article.sourceUrl);

  const rawUrl = (article.imageUrl || "").trim();
  const isBanned = (url: string) => /photo-1544620347/i.test(url) || /photo-1509749837/i.test(url);
  const isAppIcon = (url: string) => url.includes("branding/og-image.png") || url.includes("trayago.in/branding");
  const isGenericFallback = (url: string) => url.includes("og-image.png") || isAppIcon(url);

  const hasRealPhoto = Boolean(
    rawUrl &&
    isValidUrl(rawUrl) &&
    !isBanned(rawUrl) &&
    !isGenericFallback(rawUrl) &&
    !imageError
  );

  const articleUrl = `/news/${article.slug || article.id}`;
  const isHindi = /[\u0900-\u097F]/.test((article.title || "") + " " + (article.summary || ""));

  return (
    <article
      className={`group bg-card/60 border ${
        expanded
          ? "border-blue-500/50 shadow-lg shadow-blue-500/10"
          : "border-subtle/50 hover:border-blue-500/30"
      } rounded-2xl overflow-hidden transition-all duration-300 backdrop-blur-sm`}
    >
      {/* Visual Card Header / Thumbnail */}
      {hasRealPhoto ? (
        <Link
          href={articleUrl}
          onClick={() => analytics.newsArticleView(article.id, article.slug || undefined, article.category)}
          className="block w-full h-44 sm:h-52 overflow-hidden bg-card relative"
        >
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={rawUrl}
            alt={article.title}
            className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
            onError={() => setImageError(true)}
            loading="lazy"
          />
        </Link>
      ) : (
        <Link
          href={articleUrl}
          onClick={() => analytics.newsArticleView(article.id, article.slug || undefined, article.category)}
          className="block w-full h-28 sm:h-32 bg-gradient-to-r from-slate-950 via-blue-950 to-indigo-950 p-4 border-b border-subtle/50 relative overflow-hidden group-hover:from-slate-900 transition-colors"
          aria-label={`Read article: ${article.title}`}
        >
          {/* Subtle track line texture */}
          <div
            className="absolute inset-0 opacity-15 bg-[radial-gradient(#3b82f6_1.5px,transparent_1.5px)] [background-size:16px_16px]"
            aria-hidden="true"
          />
          <div className="relative z-10 h-full flex flex-col justify-between">
            <div className="flex items-center justify-between gap-2">
              <span className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-[11px] font-bold border shadow-sm ${categoryColor}`}>
                {categoryIcon}
                <span className="tracking-wide">{article.category}</span>
              </span>
              {Array.isArray(article.affectedTrains) && article.affectedTrains[0] && (
                <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-blue-500/20 text-blue-300 text-[11px] font-mono font-bold border border-blue-400/30">
                  <Train className="w-3 h-3" />
                  Train {article.affectedTrains[0]}
                </span>
              )}
            </div>
            <div className="flex items-center justify-between text-[11px] text-slate-400">
              <span className="truncate max-w-[200px]">{article.sourceName || "Indian Railways"}</span>
              <span className="inline-flex items-center gap-1 text-blue-400 group-hover:text-blue-300 font-medium">
                Read overview <ArrowRight className="w-3 h-3 group-hover:translate-x-0.5 transition-transform" />
              </span>
            </div>
          </div>
        </Link>
      )}

      <div className="p-5 sm:p-6">
        {/* Category + Source + Time row */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4">
          <div className="flex flex-wrap items-center gap-2">
            {/* Category badge */}
            <span
              className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border shadow-sm ${categoryColor}`}
            >
              {categoryIcon}
              <span className="tracking-wide">{article.category}</span>
            </span>

            {/* Source badge */}
            <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-card text-secondary border border-subtle shadow-sm max-w-[160px] truncate">
              {article.sourceName}
            </span>

            {/* Language badge */}
            <span
              className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-bold border shadow-sm ${
                isHindi
                  ? "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20"
                  : "bg-slate-500/10 text-slate-500 dark:text-slate-400 border-slate-500/20"
              }`}
            >
              {isHindi ? "🇮🇳 हिंदी" : "🌐 EN"}
            </span>
          </div>

          {/* Relative time */}
          <div className="flex items-center gap-1.5 text-xs text-muted font-medium whitespace-nowrap shrink-0">
            <Clock className="w-3.5 h-3.5" />
            <time dateTime={article.publishedAt}>{formatRelativeTime(article.publishedAt)}</time>
          </div>
        </div>

        {/* Title linked to dedicated article page */}
        <h2 className="text-lg sm:text-xl font-bold text-main mb-3 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors leading-snug">
          <Link
            href={articleUrl}
            onClick={() => analytics.newsArticleView(article.id, article.slug || undefined, article.category)}
            className="hover:underline underline-offset-2"
          >
            {article.title}
          </Link>
        </h2>

        {/* Summary */}
        {article.summary && (
          <div className="text-sm text-muted leading-relaxed mb-4">
            {expanded ? (
              <p className="whitespace-pre-wrap">{article.summary}</p>
            ) : (
              <p className="line-clamp-2 sm:line-clamp-3">{article.summary}</p>
            )}
          </div>
        )}

        {/* Affected Trains/Stations tags (internal linking) */}
        {article.affectedTrains && article.affectedTrains.length > 0 && (
          <div className="flex flex-wrap items-center gap-2 mb-4">
            <span className="text-xs text-muted font-medium flex items-center gap-1">
              <Train className="w-3 h-3 text-blue-500" /> Trains:
            </span>
            {article.affectedTrains.map((trainNo) => (
              <Link
                key={trainNo}
                href={`/live/${trainNo}`}
                onClick={() => analytics.newsTrainLinkClick(article.id, trainNo)}
                className="inline-flex items-center text-xs font-semibold px-2.5 py-0.5 rounded-md bg-blue-500/10 text-blue-600 dark:text-blue-400 border border-blue-500/20 hover:bg-blue-500/20 transition-colors"
                title={`Track Train ${trainNo}`}
              >
                #{trainNo}
              </Link>
            ))}
          </div>
        )}

        {/* Footer: Expand toggle, Dedicated Article link, and Original Source */}
        <div className="flex flex-wrap items-center justify-between border-t border-subtle pt-4 gap-3">
          {/* Expand / collapse toggle */}
          <button
            onClick={() => setExpanded(!expanded)}
            className="flex items-center gap-1.5 text-sm font-semibold text-muted hover:text-main transition-colors"
            aria-expanded={expanded}
          >
            {expanded ? (
              <>Show less <ChevronUp className="w-4 h-4" /></>
            ) : (
              <>Quick summary <ChevronDown className="w-4 h-4" /></>
            )}
          </button>

          <div className="flex items-center gap-3">
            {/* Original source link if available */}
            {hasValidUrl && (
              <a
                href={article.sourceUrl}
                target="_blank"
                rel="noopener noreferrer"
                onClick={() => analytics.newsSourceClick(article.id, article.sourceName, article.sourceUrl)}
                className="inline-flex items-center gap-1 text-xs text-muted hover:text-blue-500 transition-colors"
                title={`Read original on ${article.sourceName}`}
              >
                <ExternalLink className="w-3 h-3" />
                Original
              </a>
            )}

            {/* Read Full Coverage button */}
            <Link
              href={articleUrl}
              onClick={() => analytics.newsArticleView(article.id, article.slug || undefined, article.category)}
              className="inline-flex items-center gap-1.5 text-sm font-semibold px-3.5 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white transition-all shadow-sm hover:shadow-md active:scale-95"
            >
              Full Coverage
              <ArrowRight className="w-3.5 h-3.5" />
            </Link>
          </div>
        </div>
      </div>
    </article>
  );
}
